def read_report(stage,suite):
 log=(Path(stage)/'godot.log').read_text()
 require(not re.search(r'(?im)^\s*(?:SCRIPT ERROR:|ERROR:|FATAL:|FAIL )',log),'Error in log')
 if suite=='touch_camera_continuity_contract':
  prefix=CONTINUITY_SPEC['prefix']+' '
  rows=[l[len(prefix):] for l in log.splitlines() if l.startswith(prefix)]
  require(len(rows)==1,'Missing/duplicate continuity report')
  d=parse_json(rows[0])
  require(type(d) is dict and set(d)=={'checks','failure_count','scope'},'Wrong continuity fields')
  require(type(d['failure_count']) is int and d['failure_count']==0 and d['scope']==CONTINUITY_SPEC['scope'],'Wrong continuity result/scope')
  checks=d['checks']
  require(type(checks) is list and len(checks)==COUNTS[suite],'Wrong continuity count')
  require(all(type(x) is dict and set(x)=={'name','passed'} and x['passed'] is True for x in checks),'Failed/malformed continuity assertion')
  require([x['name'] for x in checks]==CONTINUITY_SPEC['names'],'Wrong continuity names/order')
  return d
 if suite in ARMY_CONTRACTS:
  spec=ARMY_CONTRACTS[suite];rows=[l for l in log.splitlines() if l.startswith('{')]
  require(len(rows)==1,'Missing/duplicate army report')
  d=parse_json(rows[0]);expected_keys={'suite','checks','failed'} | set(spec.get('identity',{})) | ({'scope'} if suite=='army_formation_integration' or 'scope' in spec else set()) | ({'geometry'} if suite=='wall_line_contract' else set());require(set(d)==expected_keys and d['suite']==spec['suite'] and type(d['failed']) is int and d['failed']==0,'Wrong army report identity')
  if suite=='wall_line_contract':
   geometry=d['geometry'];require(type(geometry) is list and len(geometry)==4,'Wrong wall geometry count')
   require([g.get('size') for g in geometry]==['(390, 844)','(320, 568)','(568, 320)','(1280, 800)'],'Wrong wall viewport identities')
   for g in geometry:
    require(set(g)=={'size','top','bottom','scroll','buttons','queue','summary'},'Wrong wall geometry fields')
    require(all(type(g[k]) is str and g[k] for k in ['size','top','bottom','scroll','queue','summary']),'Malformed wall geometry strings')
    require(type(g['buttons']) is list and len(g['buttons'])==7,'Wrong wall button count')
    require(all(type(b) is dict and set(b)=={'text','rect'} and all(type(v) is str and v for v in b.values()) for b in g['buttons']),'Malformed wall button geometry')
   require(geometry==WALL_LINE_GEOMETRY,'Wall controls/text/viewport layout differs from pinned seven-button contract')
  if suite=='army_formation_integration':require(d['scope']=='Controlled actual game handlers; not natural battle or rendered acceptance','Wrong formation scope')
  if 'scope' in spec:require(d['scope']==spec['scope'],'Wrong defense scope')
  for key,value in spec.get('identity',{}).items():require(type(d[key]) is type(value) and d[key]==value,'Wrong report source identity')
  checks=d['checks'];require(type(checks) is list and len(checks)==COUNTS[suite],'Wrong army assertion count')
  require([x.get('name') for x in checks]==spec['names'],'Wrong army names/order')
  require(all(type(x) is dict and set(x)=={'name',spec.get('check_field','passed')} and x[spec.get('check_field','passed')] is True for x in checks),'Failed/malformed army assertion')
  return d
 if suite in INPUT_CONTRACTS:
  spec=INPUT_CONTRACTS[suite];prefix=spec['prefix']+' '
  rows=[l[len(prefix):] for l in log.splitlines() if l.startswith(prefix)]
  require(len(rows)==1,'Missing/duplicate input report')
  checks=parse_json(rows[0])
  require(type(checks) is list and len(checks)==COUNTS[suite],'Wrong input assertion count')
  require([x.get('name') for x in checks]==spec['names'],'Wrong input names/order')
  require(all(type(x) is dict and set(x)=={'name','passed'} and x['passed'] is True for x in checks),'Failed/malformed input assertion')
  return {'checks':checks,'assertions':len(checks)}
 if suite=='resource_visual_contract':
  rows=[l for l in log.splitlines() if l.startswith('RESOURCE_CONTRACT_PASS ')]
  require(rows==['RESOURCE_CONTRACT_PASS 27'],'Wrong resource summary')
  metrics=[l for l in log.splitlines() if l.startswith('RESOURCE_METRIC ')]
  require(len(metrics)==3,'Missing/duplicate resource metrics')
  require(metrics==['RESOURCE_METRIC stone vertices=732 surfaces=1 bounds=[P: (-0.489852, 0.0, -0.398318), S: (0.979703, 0.610226, 0.796637)]', 'RESOURCE_METRIC iron vertices=930 surfaces=1 bounds=[P: (-0.489852, 0.0, -0.398318), S: (0.979703, 0.669126, 0.796637)]', 'RESOURCE_METRIC berry vertices=1800 surfaces=2 bounds=[P: (-0.460012, 0.0, -0.472095), S: (0.920025, 0.76, 0.944191)]'],'Wrong resource geometry')
  return {'summary':rows[0],'assertions':27,'metrics':metrics}
 if suite=='skirmish_policy_contract':
  rows=[l for l in log.splitlines() if l.startswith('SKIRMISH ')]
  require(rows==['SKIRMISH 17/17'],'Wrong/failed skirmish summary')
  return {'summary':rows[0],'assertions':17}
 if suite in ('resource_polish_contract','normal_probe'):
  prefix='RESOURCE_POLISH_PASS ' if suite=='resource_polish_contract' else 'NORMALS_PASS '
  rows=[l for l in log.splitlines() if l.startswith(prefix)]
  require(rows==[prefix+str(COUNTS[suite])],'Wrong/failed geometry summary')
  return {'summary':rows[0],'assertions':COUNTS[suite]}
 if suite=='material_contract':
  rows=[l for l in log.splitlines() if l.startswith('FOG_MATERIAL_CONTRACT ')]
  require(rows==['FOG_MATERIAL_CONTRACT checks=13 failures=0'],'Wrong material summary')
  return {'summary':rows[0],'assertions':13}
 require(suite=='continuous_training_contract','Unknown suite')
 rows=[l for l in log.splitlines() if l.startswith('{')];require(len(rows)==1,'Missing/duplicate training report')
 d=parse_json(rows[0]);require(d.get('suite')==suite and d.get('failed')==0,'Wrong/failed training report')
 from run_export import BUILD
 require(d.get('build')==BUILD,'Wrong training build')
 checks=d.get('checks');require(type(checks) is list and len(checks)==16,'Missing training checks')
 require([x.get('name') for x in checks]==TRAINING_NAMES and all(x.get('passed') is True for x in checks),'Wrong/failed training checks')
 return d

